def _base164_decode(text: str) -> str:
    alphabet = BASE164_ALPHABET
    cleaned = re.sub(r"[^АВСЕМA-Za-z0-9.,~]", "", text)
    out = []
    i = 0
    while i < len(cleaned):
        a = alphabet.find(cleaned[i]) if i < len(cleaned) else -1
        i += 1
        s = alphabet.find(cleaned[i]) if i < len(cleaned) else -1
        i += 1
        r = alphabet.find(cleaned[i]) if i < len(cleaned) else -1
        i += 1
        d = alphabet.find(cleaned[i]) if i < len(cleaned) else -1
        i += 1
        if a < 0 or s < 0:
            break
        n1 = (a << 2) | (s >> 4)
        n2 = ((15 & s) << 4) | (max(r, 0) >> 2)
        n3 = ((3 & max(r, 0)) << 6) | max(d, 0)
        out.append(chr(n1 & 255))
        if r != 64:
            out.append(chr(n2 & 255))
        if d != 64:
            out.append(chr(n3 & 255))
    decoded = "".join(out)
    decoded = re.sub(r"%u([0-9A-Fa-f]{4})", lambda m: chr(int(m.group(1), 16)), decoded)
    decoded = re.sub(r"%([0-9A-Fa-f]{2})", lambda m: chr(int(m.group(1), 16)), decoded)
    return decoded


