        files = _http_json(f"{origin}/api/videofile.php?video_id={video_id}&lifetime=8640000", url)
    except (urllib.error.URLError, TimeoutError, OSError, json.JSONDecodeError):
        return None
    if not isinstance(files, list) or not files:
